package org.nonfood.oilplants.dao;
import org.junit.jupiter.api.Test;import org.nonfood.oilplants.model.PlantSearchCriteria;import java.math.BigDecimal;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class PlantQueryTest {
 @Test void bindsInputAndUsesOneSampleForOilAndComponent(){PlantSearchCriteria c=new PlantSearchCriteria();c.setKeyword("x%' OR 1=1 --");c.setOilMin(new BigDecimal("60"));c.setComponentName("oleic");c.setComponentMin(new BigDecimal("10"));PlantQuery.Built b=PlantQuery.search(c,false,false);assertFalse(b.sql().contains("1=1 --"));assertTrue(b.parameters().contains("%x!%' OR 1=1 --%"));assertTrue(b.sql().contains("s.plant_id=p.id"));assertTrue(b.sql().contains("fc.sample_id=s.id"));assertTrue(b.sql().contains("s.oil_content_pct>=?"));assertTrue(b.sql().contains("fc.percentage>=?"));}
 @Test void wildcardCharactersAreLiteralInFuzzySearch(){PlantSearchCriteria c=new PlantSearchCriteria();c.setKeyword("leaf_%!");var b=PlantQuery.search(c,false,false);assertTrue(b.sql().contains("LIKE ? ESCAPE '!'"));assertTrue(b.parameters().contains("%leaf!_!%!!%"));}
 @Test void sortInputNeverBecomesSql(){PlantSearchCriteria c=new PlantSearchCriteria();c.setSort("name; DROP TABLE plants");c.setDirection("desc; DROP");String sql=PlantQuery.search(c,false,true).sql();assertTrue(sql.endsWith("ORDER BY p.name_zh ASC, p.id ASC"));assertFalse(sql.contains("DROP"));}
 @Test void exactMatchUsesEqualityAndKeepsInputAsAParameter(){PlantSearchCriteria c=new PlantSearchCriteria();c.setKeyword("exact name");c.setExact(true);var b=PlantQuery.search(c,false,false);assertTrue(b.sql().contains("p.name_zh = ?"));assertFalse(b.sql().contains("LIKE"));assertEquals(List.of("exact name","exact name","exact name","exact name","exact name","exact name","exact name","exact name","exact name"),b.parameters());}
 @Test void numericBasicSearchUsesDecimalEquality(){PlantSearchCriteria c=new PlantSearchCriteria();c.setKeyword("25.5");var b=PlantQuery.search(c,false,false);assertTrue(b.sql().contains("kn.oil_content_pct=?"));assertTrue(b.sql().contains("fn.percentage=?"));assertTrue(b.parameters().contains(new BigDecimal("25.5")));assertFalse(b.sql().contains("CAST(kn.oil_content_pct"));}
 @Test void visitorQueryExcludesPrivateRecords(){PlantSearchCriteria c=new PlantSearchCriteria();assertTrue(PlantQuery.search(c,false,false).sql().contains("p.is_public=1"));assertFalse(PlantQuery.search(c,true,false).sql().contains("p.is_public=1"));}
 @Test void unverifiedAliasesAreHiddenFromPublicSearchButRemainFindableToAdmins(){PlantSearchCriteria c=new PlantSearchCriteria();c.setKeyword("pending");assertTrue(PlantQuery.search(c,false,false).sql().contains("a.source_status='VERIFIED'"));assertFalse(PlantQuery.search(c,true,false).sql().contains("a.source_status='VERIFIED'"));}
}
